                    out[r][x] = color

    # Rays from a border stripe's endpoints run inward in that stripe's color.
    for edge in (0, w - 1):
        rs = [r for r in range(h) if grid[r][edge] != bg]
        if len(rs) >= 2:
            col = grid[rs[0]][edge]
            for r in (min(rs), max(rs)):
